import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

function fakeFetch(query) {
  // Shorter queries reply faster — easy to trigger the race
  const delay = query.length < 3 ? 50 : 300;
  return new Promise((resolve) =>
    setTimeout(() => resolve('Results for: ' + query), delay)
  );
}

function App() {
  const [query, setQuery] = useState('react');
  const [result, setResult] = useState('');

  useEffect(() => {
    fakeFetch(query).then(setResult);
  }, [query]);

  return (
    <div>
      <input
        id="query"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      <p id="result">{result}</p>
    </div>
  );
}

export default App;

