import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Slow Reply', () => {
  test('Input and result render', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#query');
const result = root.querySelector('#result');
if (!input) throw new Error('No input with id "query" found');
if (!result) throw new Error('No element with id "result" found');
  });

  test('The latest query\u2019s result is the one that lands', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#query');
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
// Initial render kicked off the slow fetch for "react" (300ms)
// Now switch to a short query that responds fast (50ms)
setter.call(input, 'r');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
// Wait long enough for BOTH fetches to resolve
await new Promise(r => setTimeout(r, 500));
const text = root.querySelector('#result').textContent.trim();
if (text !== 'Results for: r')
  throw new Error('Expected result for the latest query "r", got: "' + text + '"');
  });
});
